  async function loadCaseConversation(before=''){
    const route=sourceRoute(),token=++caseHistoryToken,list=$('caseConversationMessages'),status=$('caseHistoryStatus'),older=document.querySelector('[data-case-history-earlier]');
    if(!route?.lead_id){caseHistory=detail?.evidence||[];renderConversation(caseHistory);renderBoundarySelectors();status.textContent=caseHistory.length?'':u('noRoute');return;}
    if(before&&older)older.disabled=true;
    if(!before){caseHistory=[];caseHistoryBefore=null;status.textContent=u('loadingHistory');list.innerHTML='';}
    const query=new URLSearchParams({provider:route.provider||'connect',lead_id:route.lead_id,channel_id:route.channel_id||'',conversation_id:route.conversation_id||'',...expected()});
    if(before)query.set('before',before);
    const oldHeight=list.scrollHeight,oldTop=list.scrollTop;
    try{
      const result=await api('/api/platform/ai/dialogs/history?'+query);if(token!==caseHistoryToken||!$('supportCaseModal'))return;
      const incoming=Array.isArray(result.messages)?result.messages:[];
      caseHistory=before?incoming.concat(caseHistory):incoming;caseHistoryBefore=result.next_before||null;
      renderConversation(caseHistory);status.textContent=caseHistory.length?'':u('noMessages');
      if(older){older.hidden=!caseHistoryBefore;older.disabled=false;}
      if(before)list.scrollTop=list.scrollHeight-oldHeight+oldTop;else list.scrollTop=list.scrollHeight;
    }catch(error){
      if(token!==caseHistoryToken||!$('supportCaseModal'))return;
      if(!before&&detail?.evidence?.length){caseHistory=detail.evidence;renderConversation(caseHistory);}
      status.textContent=u('historyError');
      if(older)older.disabled=false;
    }
  }
