  function setPeriodPreset(){const preset=$('casesPeriodPreset'),from=$('casesFrom'),to=$('casesTo');if(!preset)return;const days=Number(preset.value);const custom=!days;from.disabled=!custom;to.disabled=!custom;if(custom)return;const end=new Date(),start=new Date(end);start.setDate(start.getDate()-(days-1));from.value=dateValue(start);to.value=dateValue(end);}
