  async function prepare(){if(!member||!root())return;clearTimeout(pollTimer);generation++;batchId=null;batchState=null;cards=[];nextBefore=null;render();try{const results=await Promise.all([api('/api/platform/ai/dialogs'),api('/api/platform/ai/agents'),api('/api/platform/ai/channels?'+new URLSearchParams(expected()))]);dialogs=results[0].dialogs||[];agents=Array.isArray(results[1])?results[1]:results[1].agents||[];channels=results[2].channels||[];populateChannels();await load();const settings=document.querySelector('#view-settings');if(settings)await window.TenantKnowledgeCampaigns?.mount(settings,{channels,agents,api,expected,lang,refreshCards:()=>load()});}catch(error){notice(error.message);}}
  document.addEventListener('tenant-profile',event=>{caseReturnPending=false;clearTimeout(pollTimer);generation++;clearCaseMedia(true);$('supportCaseModal')?.remove();cards=[];dialogs=[];channels=[];agents=[];selected=null;detail=null;batchRequest=null;batchId=null;batchState=null;if(root())root().innerHTML='';member=event.detail?.member||null;if(member&&['owner','admin'].includes(member.role))prepare();});
  document.addEventListener('tenant-view',event=>{if(event.detail?.view!=='support_cases')return;const modal=$('supportCaseModal');if(caseReturnPending&&modal){modal.style.display='';caseReturnPending=false;return;}prepare();});
